using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class ReplaceComboSkill03{
 public static object Run(){if(Application.isPlaying)throw new Exception("Stop play first");var skill=GameObject.Find("Attack 05 - Skill_03");var live=GameObject.Find("New Knight Combo Sequence Preview");var a=live.GetComponentInChildren<Animator>();var clip=a.runtimeAnimatorController.animationClips[0];string path=AssetDatabase.GetAssetPath(clip);AssetDatabase.CopyAsset(path,AssetDatabase.GenerateUniqueAssetPath(path.Replace(".anim","_BeforeSkillReplacement.anim")));var original=UnityEngine.Object.Instantiate(clip);var clone=UnityEngine.Object.Instantiate(skill);var sa=clone.GetComponentInChildren<Animator>();sa.enabled=false;var source=sa.runtimeAnimatorController.animationClips[0];var bindings=AnimationUtility.GetCurveBindings(clip);Func<float,bool> inside=t=>t<=16f/30f+.00001f||(t>=156f/30f-.00001f&&t<=172f/30f+.00001f);var transforms=bindings.Select(b=>b.path).Distinct().ToDictionary(p=>p,p=>sa.transform.Find(p));var data=bindings.ToDictionary(b=>b,b=>new List<Keyframe>());try{foreach(int start in new[]{0,156})for(int i=0;i<=128;i++){float time=i/240f;source.SampleAnimation(sa.gameObject,time);foreach(var b in bindings){var t=transforms[b.path];int axis="xyzw".IndexOf(b.propertyName.Last());float value=b.propertyName.StartsWith("m_LocalPosition")?t.localPosition[axis]:b.propertyName.StartsWith("m_LocalRotation")?t.localRotation[axis]:t.localScale[axis];data[b].Add(new Keyframe(start/30f+time,value));}}
 Undo.RecordObject(clip,"Replace combo skill3 segments");foreach(var b in bindings){var old=AnimationUtility.GetEditorCurve(original,b);var keys=old.keys.Where(k=>!inside(k.time)).Concat(data[b]).OrderBy(k=>k.time).ToArray();var curve=new AnimationCurve(keys);for(int i=0;i<curve.length;i++){AnimationUtility.SetKeyLeftTangentMode(curve,i,AnimationUtility.TangentMode.Linear);bool cut=new[]{16,51,93,155,172,218,303}.Any(f=>Mathf.Abs(curve.keys[i].time-f/30f)<.00001f);AnimationUtility.SetKeyRightTangentMode(curve,i,cut?AnimationUtility.TangentMode.Constant:AnimationUtility.TangentMode.Linear);}AnimationUtility.SetEditorCurve(clip,b,curve);}
 // Quaternion signs may differ between source clips. All boundaries are hard cuts.
 float error=0,positionError=0,otherError=0;var target=UnityEngine.Object.Instantiate(live);var ta=target.GetComponentInChildren<Animator>();ta.enabled=false;try{for(int f=0;f<=303;f++){float t=f/30f;if(inside(t)){source.SampleAnimation(sa.gameObject,(f<17?f:f-156)/30f);clip.SampleAnimation(ta.gameObject,t);foreach(var p in transforms.Keys){var x=transforms[p];var y=ta.transform.Find(p);error=Mathf.Max(error,Quaternion.Angle(x.localRotation,y.localRotation));positionError=Mathf.Max(positionError,Vector3.Distance(x.localPosition,y.localPosition));}}else{original.SampleAnimation(ta.gameObject,t);var poses=transforms.Keys.ToDictionary(p=>p,p=>ta.transform.Find(p).localRotation);clip.SampleAnimation(ta.gameObject,t);foreach(var p in poses.Keys)otherError=Mathf.Max(otherError,Quaternion.Angle(poses[p],ta.transform.Find(p).localRotation));}}}finally{UnityEngine.Object.DestroyImmediate(target);}if(error>.1f||otherError>.1f)throw new Exception("Validation failed: "+error+" / "+otherError);EditorUtility.SetDirty(clip);AssetDatabase.SaveAssets();clip.SampleAnimation(a.gameObject,0);var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return new{segments="0-16,156-172",source=source.name,maxRotationError=error,maxPositionError=positionError,otherSegmentError=otherError,length=clip.length};}catch{EditorUtility.CopySerialized(original,clip);EditorUtility.SetDirty(clip);AssetDatabase.SaveAssets();throw;}finally{UnityEngine.Object.DestroyImmediate(original);UnityEngine.Object.DestroyImmediate(clone);}}
